### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> A(n);
    for (int i = 0; i < n; ++i) {
        cin >> A[i];
    }

    const int MAX_VAL = 1000005;
    vector<int> cnt(MAX_VAL, 0);
    int diff = 0;
    int ans = 0;

    deque<int> max_q, min_q; // 分别维护最大值和最小值索引

    for (int i = 0; i < n; ++i) {
        int x = A[i];
        // 加入当前元素
        cnt[x]++;
        if (cnt[x] == 1) diff++;

        // 维护递减的最大值队列
        while (!max_q.empty() && A[max_q.back()] <= x) {
            max_q.pop_back();
        }
        max_q.push_back(i);

        // 维护递增的最小值队列
        while (!min_q.empty() && A[min_q.back()] >= x) {
            min_q.pop_back();
        }
        min_q.push_back(i);

        // 窗口长度超出k，移除左边界
        if (i >= k) {
            int left_val = A[i - k];
            cnt[left_val]--;
            if (cnt[left_val] == 0) diff--;
        }

        // 弹出过期索引
        int left = i - k + 1;
        while (!max_q.empty() && max_q.front() < left) {
            max_q.pop_front();
        }
        while (!min_q.empty() && min_q.front() < left) {
            min_q.pop_front();
        }

        // 判断长度为k的窗口
        if (i >= k - 1) {
            if (diff == k) {
                int max_val = A[max_q.front()];
                int min_val = A[min_q.front()];
                if (max_val - min_val == k - 1) {
                    ans++;
                }
            }
        }
    }

    cout << ans << '\n';
    return 0;
}
